import { B as BASE_API_URL } from "../../../../../../../../chunks/constants.js";
import { error } from "@sveltejs/kit";
const GET = async ({ fetch, params }) => {
  const URLModel = "compliance-assessments";
  const endpoint = `${BASE_API_URL}/${URLModel}/${params.id}/xlsx/`;
  const res = await fetch(endpoint);
  if (!res.ok) {
    error(400, "Error fetching the Excel file");
  }
  const fileName = `audit-${params.id}.xlsx`;
  return new Response(await res.blob(), {
    headers: {
      "Content-Type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      "Content-Disposition": `attachment; filename="${fileName}"`
    }
  });
};
export {
  GET
};
